import{_ as t,o as n,c as s,a4 as o}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse('{"title":"ADR-0073 — Contrôle de soumission déclaré par une extension, et longueur maximale des textes longs","description":"Extrait de docs/adr/0073-controle-de-soumission-et-longueur-des-textes-longs.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0073 — Contrôle de soumission déclaré par une extension, et longueur maximale des textes longs","description":"Extrait de docs/adr/0073-controle-de-soumission-et-longueur-des-textes-longs.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0073-controle-de-soumission-et-longueur-des-textes-longs.md","filePath":"developpeurs/adr/0073-controle-de-soumission-et-longueur-des-textes-longs.md"}'),r={name:"developpeurs/adr/0073-controle-de-soumission-et-longueur-des-textes-longs.md"};function i(a,e,u,l,c,d){return n(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0073--contrôle-de-soumission-déclaré-par-une-extension-et-longueur-maximale-des-textes-longs" tabindex="-1">ADR-0073 — Contrôle de soumission déclaré par une extension, et longueur maximale des textes longs <a class="header-anchor" href="#adr-0073--contrôle-de-soumission-déclaré-par-une-extension-et-longueur-maximale-des-textes-longs" aria-label="Permalink to &quot;ADR-0073 — Contrôle de soumission déclaré par une extension, et longueur maximale des textes longs {#adr-0073--contrôle-de-soumission-déclaré-par-une-extension-et-longueur-maximale-des-textes-longs}&quot;">​</a></h1><p><strong>Date :</strong> 17 octobre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> issue #32 (lot 25) ; arbitrages du Product Owner du 17/10/2026 (appliquer les deux limites que les extensions livrées documentaient comme « non contrôlées » : les 150 caractères du texte d&#39;un flash info, les questions obligatoires d&#39;une enquête) <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0002-frontiere-core-plugins">ADR-0002</a> — un neuvième point d&#39;extension du SDK, <code>register_submission_check</code>, que le manifeste d&#39;une extension déclare (<code>submission_checks</code>) ; la frontière ne bouge pas : une extension n&#39;importe toujours que <code>app.plugins</code>, et le Core ne connaît aucune extension.</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Deux extensions livrées décrivaient, dans leur code, une règle du corpus qu&#39;elles ne faisaient pas respecter :</p><ul><li><strong>Flash info</strong> (<code>FLASH_INFO.docx</code>) : le texte du message est limité à 150 caractères. <code>LongTextFieldDef</code> ne portait aucune longueur maximale ; la limite n&#39;existait que dans l&#39;aide du champ, qui disait « la limite n&#39;est pas contrôlée à la saisie ». Un agent pouvait enregistrer 400 caractères et découvrir le dépassement au rendu.</li><li><strong>Enquêtes</strong> (<code>ENQUETES.docx</code>, F105) : une question peut être marquée <code>obligatoire</code>. La décision n°4 de l&#39;extension notait que cette indication n&#39;était « jamais appliquée » : la vérifier suppose de confronter la réponse déposée (un enregistrement du Content Type <code>enquete_reponse</code>) aux questions de l&#39;<code>enquete</code> qu&#39;elle référence — <strong>deux enregistrements</strong> de deux Content Types. <code>validate_submission</code> valide un formulaire contre son propre schéma et ne sait pas lire un autre enregistrement ; et le Core ne doit pas connaître les enquêtes (ADR-0002). L&#39;aide de la case disait : « cette indication n&#39;est pas contrôlée à l&#39;envoi ».</li></ul><p>Dans les deux cas, une exigence annoncée à l&#39;agent et au public n&#39;était pas tenue : l&#39;usager remplit une enquête dont les questions « obligatoires » ne le sont pas, et le résultat est un jeu de réponses incomplet que l&#39;on ne peut plus compléter.</p><p>Une troisième constatation a été faite en cours de route, et elle est consignée plutôt que passée sous silence : <strong><code>TextFieldDef.max_length</code> (texte court) est déclaré, publié aux clients (l&#39;admin et le formulaire public posent <code>maxlength</code>) mais n&#39;est pas appliqué par le validateur du serveur.</strong> Le titre du flash info (55 caractères) en est un exemple ; la docstring de l&#39;extension affirmait le contraire.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. <code>LongTextFieldDef.max_length</code> : une longueur maximale, appliquée par le Field Engine.</strong></p><ul><li>Entier, <strong>1 à 50 000</strong> (<code>LONG_TEXT_MAX_LENGTH</code>), facultatif : sans valeur, rien ne change.</li><li>Compté en <strong>caractères</strong> (points de code), un saut de ligne pour un. Appliqué par <code>build_dynamic_model</code>, le constructeur unique des surfaces qui valident des champs déclarés : écriture d&#39;un enregistrement au back-office (<code>POST</code> et <code>PUT …/entries</code>), soumission publique <strong>et</strong> correction depuis la page de relecture, charge utile d&#39;un bloc. La règle est écrite une fois.</li><li>Erreur française <strong>par champ</strong> : « ce texte compte 151 caractères, la limite est de 150 caractères : raccourcissez-le » — 422 (<code>loc</code> sur le champ au back-office ; <code>FormValidationError</code>, une erreur par champ, en soumission publique). Le texte saisi n&#39;est pas renvoyé dans l&#39;erreur publique.</li><li><strong>Texte riche : pas de <code>max_length</code>.</strong> Sa valeur est du balisage ; compter le texte visible suppose d&#39;interpréter ce balisage côté serveur, avec une analyse qui n&#39;est pas celle du rendu. Le texte long simple est seul concerné.</li><li><strong>Données existantes plus longues que la limite : la lecture ne casse pas</strong> (rien ne relit la longueur à la lecture, ni à la liste, ni au rendu public). <strong>La modification ultérieure de l&#39;enregistrement doit respecter la limite</strong> : l&#39;écriture revalide toutes les données, donc l&#39;agent doit raccourcir le texte, même s&#39;il ne modifie qu&#39;un autre champ. C&#39;est voulu — une limite qui s&#39;appliquerait seulement aux champs touchés exigerait de comparer à l&#39;ancienne valeur — et c&#39;est dit à l&#39;agent (aide de l&#39;éditeur de schéma, compteur de saisie).</li><li><strong>Flash info : <code>texte</code> porte <code>max_length=150</code></strong> ; la docstring et l&#39;aide (<code>plugins.flash_info.aide.texte</code>) disent désormais que la limite est contrôlée.</li><li><strong>Admin</strong> : le champ de texte long pose <code>maxlength</code>, affiche « N caractères sur 150 autorisés » en texte visible, relié au champ par <code>aria-describedby</code> (la couleur n&#39;est qu&#39;un renfort : le texte dit aussi le dépassement) ; l&#39;éditeur de schéma règle la « longueur maximale » d&#39;un texte long comme celle d&#39;un texte court. <strong>Front public</strong> : même <code>maxlength</code> et même mention, lus dans le descripteur du formulaire.</li></ul><p><strong>2. Le contrôle de soumission : un point d&#39;extension du SDK.</strong></p><ul><li><p>Une extension déclare, dans <code>PluginManifest.submission_checks</code>, un <code>SubmissionCheck(owner, content_type_key, check, timeout_seconds)</code> : pour <strong>un de ses Content Types de formulaire</strong>, une fonction <code>async</code> que le Core appelle avant d&#39;accepter une soumission publique. Exportés par <code>app.plugins</code> : <code>SubmissionCheck</code>, <code>SubmissionCheckError</code>, <code>SubmissionCheckInput</code>, <code>PublishedRecord</code>, <code>PublishedRecordReader</code>, <code>register_submission_check</code>.</p></li><li><p><strong>Signature</strong> : <code>async def controle(contexte: SubmissionCheckInput) -&gt; Sequence[SubmissionCheckError]</code>. <code>contexte.data</code> : les données soumises, <strong>déjà validées</strong> contre le schéma du formulaire et copiées (la fonction ne peut pas modifier la soumission) ; <code>contexte.read_published(content_type_key, entry_id)</code> : la seule lecture offerte. <code>SubmissionCheckError(field, message)</code> : un champ, un message français ; le code d&#39;erreur (<code>field.invalid</code>) est celui du Core.</p></li><li><p><strong>Lecture restreinte.</strong> <code>read_published</code> rend un <code>PublishedRecord(id, content_type_key, data)</code> — une <strong>copie</strong> — d&#39;un enregistrement <strong>publié et public</strong> (mêmes clauses que les surfaces publiques : état publié, visibilité publique, fin de publication non échue) <strong>de l&#39;organisation de la soumission</strong>, du Content Type demandé, sans les champs <code>public=False</code>. Elle rend <code>None</code>, sans distinction, pour un identifiant inconnu, illisible, d&#39;une autre organisation, en brouillon, non public, échu, ou d&#39;un <strong>type ou d&#39;un champ porteur de données personnelles</strong> (une lecture que le journal d&#39;accès RGPD ne verrait pas). Pas de session SQL, pas d&#39;écriture, pas d&#39;énumération.</p></li><li><p><strong>Quand.</strong> À l&#39;ouverture de la soumission (avant toute écriture), à la <strong>correction</strong> depuis la page de relecture, et à la <strong>confirmation</strong> : l&#39;enregistrement lu (une enquête) a pu être dépublié pendant que l&#39;usager relisait, et c&#39;est cette étape qui écrit le contenu. La confirmation ne reçoit toujours aucune donnée : le contrôle y lit celles de la soumission déjà enregistrée. Il passe après la validation structurelle et avant l&#39;intégrité référentielle : une enquête inconnue est signalée sur le champ <code>enquete</code>.</p></li><li><p><strong>Sortie.</strong> Les erreurs rendues deviennent une <code>FormValidationError</code> (422), <strong>une erreur par champ</strong> (les messages d&#39;un même champ sont réunis ; un champ que le formulaire ne déclare pas est ramené sur <code>_</code>) ; rien n&#39;est écrit.</p></li><li><p><strong>Bornes.</strong> Une seule fonction par Content Type (registre et manifeste) ; fonction <strong>asynchrone</strong> (une fonction synchrone bloquerait la boucle d&#39;événements du serveur : refusée à la déclaration) ; délai <strong>2 s par défaut, 5 s au plus</strong> ; 50 erreurs au plus, 500 caractères par message. Un contrôle ne vaut que pour un type <strong>provisionné par le même manifeste</strong> et qui porte un <code>form_config</code> : déclarer pour le type d&#39;une autre extension, ou d&#39;un type qui ne se remplit pas publiquement, est refusé à la construction du manifeste, avec les autres fautes du manifeste. Désinstaller l&#39;extension retire son contrôle (registre construit sur les extensions actives de l&#39;organisation).</p></li><li><p><strong>Si la fonction échoue, la soumission est refusée — jamais acceptée par défaut</strong> (même principe que l&#39;ADR-0027 pour un service configuré mais injoignable) :</p><ul><li><strong>exception → 500</strong>, message générique, journalisé avec le nom de l&#39;extension, le Content Type, la <strong>classe</strong> de l&#39;exception et son emplacement dans le code — <strong>jamais le message de l&#39;exception ni la trace</strong>, qui peuvent citer une donnée saisie (une <code>KeyError(&#39;Jeanne Dupont&#39;)</code>) ;</li><li><strong>dépassement du délai → 503</strong>.</li></ul><p>La distinction est celle du reste du dépôt : une exception est un défaut du code de l&#39;extension, que réessayer ne corrige pas — un 503 inviterait le client à réessayer en boucle un défaut permanent ; un délai dépassé est une indisponibilité, l&#39;usager peut réessayer. Dans les deux cas, ni donnée personnelle dans la réponse ni dans le journal.</p></li><li><p><strong>Enquête</strong> : <code>controler_reponse_enquete</code> lit l&#39;enquête référencée par <code>read_published</code> et refuse (a) une enquête introuvable ou non publiée — erreur sur le champ <code>enquete</code> ; (b) une réponse sans valeur <strong>non vide</strong> pour une question <code>obligatoire=True</code> — erreur sur le champ <code>reponses</code>, qui nomme jusqu&#39;à trois questions manquantes (puis « et N autres »). La question est reconnue par son texte recopié, espaces normalisés. Seule la <strong>présence</strong> d&#39;une valeur est contrôlée, pas sa forme (une grille Likert dont une rangée est remplie compte comme répondue). L&#39;aide <code>plugins.enquetes.aide.obligatoire</code> et la décision n°4 de la docstring sont réécrites.</p></li></ul><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Retirer la case « obligatoire » de l&#39;enquête, et la limite de 150 caractères du flash info</strong></td><td>Efface l&#39;exigence du corpus au lieu de la tenir. L&#39;agent perd un réglage que le public attend ; le jour où l&#39;on veut le rétablir, les enquêtes déjà saisies n&#39;ont plus la donnée.</td></tr><tr><td><strong>Garder les deux limites comme aide de champ</strong> (état d&#39;avant)</td><td>Une consigne que rien n&#39;oppose est ignorée au premier dépassement, et le dépassement ne se voit qu&#39;au rendu.</td></tr><tr><td><strong>Mettre la règle des enquêtes dans le Core</strong> (<code>if form == &quot;enquete_reponse&quot;</code>)</td><td>Viole l&#39;ADR-0002 : le Core connaîtrait une extension. Le test structurel <code>test_plugin_sdk.py</code> et la revue l&#39;interdisent à juste titre.</td></tr><tr><td><strong>Donner à la fonction de l&#39;extension la session SQL</strong></td><td>Une extension pourrait lire n&#39;importe quelle table, d&#39;une autre organisation, écrire, ou lire des données personnelles sans journal. La lecture restreinte offre ce dont le besoin est fait — un enregistrement publié, par identifiant — et rien d&#39;autre.</td></tr><tr><td><strong>Une route ou un champ de schéma « validation croisée » générique</strong> (<code>must_reference: {champ, règle}</code>)</td><td>Un langage de règles de plus à maintenir pour un cas ; le cas suivant (contrôle de quota, de doublon) ne tiendrait pas dedans. Une fonction est plus pauvre à spécifier et plus simple à tester.</td></tr><tr><td><strong>Plusieurs fonctions par type</strong></td><td>L&#39;ordre et l&#39;agrégation des erreurs deviennent des sujets. Une extension compose ses règles dans sa fonction ; le Core garde une seule frontière à borner.</td></tr><tr><td><strong>Exception de la fonction → accepter la soumission</strong></td><td>Un contrôle cassé deviendrait une porte ouverte ; l&#39;usager ne le saurait pas. Contraire à l&#39;ADR-0027.</td></tr><tr><td><strong>Exception → 503 comme le délai</strong></td><td>Un défaut permanent présenté comme transitoire : le client réessaie, l&#39;exploitant ne voit qu&#39;une indisponibilité.</td></tr><tr><td><strong>Appliquer aussi <code>max_length</code> au texte court dans ce lot</strong></td><td>Rend invalides à l&#39;écriture, d&#39;un coup, des enregistrements de tous les Content Types qui déclarent déjà un <code>max_length</code> (dans les extensions livrées comme dans les schémas créés par les agents), pour un besoin que l&#39;issue ne formule pas. Décision à part, consignée en action ouverte.</td></tr><tr><td><strong>Une limite sur le texte riche, comptée sur le balisage</strong></td><td>Une limite de 150 « caractères » qui compterait <code>&lt;strong&gt;</code> fausse son sens pour l&#39;agent ; la compter sur le texte visible demande un analyseur HTML côté serveur. Hors lot.</td></tr><tr><td><strong>Contrôler la longueur à la lecture, rejeter ou tronquer l&#39;existant</strong></td><td>Casse des pages publiées ou perd du texte en silence. La lecture reste intacte ; seule l&#39;écriture ultérieure exige de raccourcir.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Les 150 caractères du flash info et les questions obligatoires d&#39;une enquête sont enfin tenus côté serveur, au back-office comme en public ; une enquête n&#39;accepte plus de réponse partielle sur ses questions obligatoires.</li><li>Le SDK gagne un point d&#39;extension sans exception à l&#39;ADR-0002 : la règle d&#39;une extension s&#39;exprime dans l&#39;extension, le Core ne connaît ni le nom « enquête » ni sa structure. Toute extension future (quota d&#39;inscriptions, doublon de candidature) l&#39;emploie sans toucher au Core.</li><li>La longueur maximale d&#39;un texte long est utilisable par tout Content Type et se règle dans l&#39;éditeur de schéma.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Un texte déjà plus long que la limite ne peut plus être enregistré tel quel</strong> : modifier un autre champ de l&#39;enregistrement oblige à raccourcir ce texte. Aucune migration ne l&#39;a raccourci ; aucun enregistrement existant n&#39;est modifié.</li><li><strong>Une fonction d&#39;extension est du code qui s&#39;exécute dans le chemin d&#39;une requête publique</strong>, sur le serveur. Les bornes (asynchrone, délai, une fonction, lecture restreinte) limitent le dégât d&#39;une extension fautive sans l&#39;annuler : une fonction qui consomme du processeur sans céder la main n&#39;est pas interrompue par un délai (limite d&#39;<code>asyncio</code>). Le chargement dynamique de code tiers reste hors périmètre (ADR-0002) : ces fonctions sont celles des extensions du dépôt.</li><li><strong>Une requête de plus</strong> (les extensions actives de l&#39;organisation) à l&#39;ouverture, à la correction et à la confirmation d&#39;un formulaire public, (la confirmation en fait désormais deux : gabarits, puis contrôle) ; plus une lecture par contrôle qui lit. Le registre n&#39;est pas mis en cache (ADR-0016 : pas de cache sans mesure).</li><li><strong>Le contrôle des enquêtes ne regarde que la présence d&#39;une réponse</strong>, pas sa forme, et reconnaît la question par son texte recopié : une enquête corrigée après coup (intitulé modifié) puis répondue avec l&#39;ancien intitulé est refusée tant que l&#39;intitulé n&#39;est pas celui d&#39;aujourd&#39;hui.</li><li><strong><code>TextFieldDef.max_length</code> reste non appliqué côté serveur</strong> (cf. Contexte) : l&#39;écart entre ce qui est affiché à l&#39;agent et ce que le serveur tient subsiste pour le texte court.</li><li><strong>Le front public ne rend pas encore les enquêtes</strong> : <code>ChampFormulaire.vue</code> n&#39;a pas de branche pour un répéteur, donc le champ <code>reponses</code> ne peut pas être saisi question par question sur le site ; <code>required</code>/<code>aria-required</code> par question n&#39;a pas de support. Sans objet pour le serveur, qui refuse désormais la réponse incomplète ; à traiter avec le rendu des enquêtes.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] <code>LongTextFieldDef.max_length</code> (1 à 50 000), appliqué par le Field Engine à l&#39;écriture au back-office, en soumission publique et à la correction, avec erreur française par champ ; flash info <code>texte</code> à 150, docstring et aide réécrites. — <code>apps/api/app/content/fields.py</code> (<code>LongTextFieldDef</code>, <code>_check_long_text_length</code>, <code>LONG_TEXT_MAX_LENGTH</code>), <code>apps/api/app/bundled_plugins/flash_info.py</code>. Preuves : <code>apps/api/tests/test_flash_info.py::test_le_texte_de_150_caracteres_est_accepte_et_celui_de_151_est_refuse</code> (<strong>rouge avant</strong> : le texte de 151 caractères était accepté, 201 au lieu de 422 ; vert ensuite) et <code>test_le_champ_texte_du_flash_info_declare_sa_limite_et_son_aide_ne_ment_plus</code> ; <code>apps/api/tests/test_controle_de_soumission.py</code> (texte long de N caractères accepté, N+1 refusé, au back-office, en soumission publique et à la correction ; donnée existante plus longue lisible puis refusée à la réécriture ; descripteur public) ; <code>ruff</code> et <code>flake8</code> verts ; suite complète le 17/10/2026 : 2 433 tests réussis, 1 ignoré (2 404 au départ, +29 : 2 flash info, 2 enquêtes, 25 dans <code>test_controle_de_soumission.py</code>).</li><li>[x] Admin et front : compteur et <code>maxlength</code> sur le texte long, « longueur maximale » réglable pour un texte long dans l&#39;éditeur de schéma. — <code>apps/admin/components/fields/FieldLongText.vue</code>, <code>components/contenus/SchemaFieldEditor.vue</code>, <code>utils/contentSchemaEditor.ts</code>, <code>types/api.ts</code> ; <code>apps/front/components/socle/ChampFormulaire.vue</code>, <code>assets/css/socle.css</code>. Preuves : <code>lint</code>, <code>typecheck</code> et <code>build</code> de l&#39;admin et du front verts le 17/10/2026, <code>npm test</code> du front vert (294 tests).</li><li>[x] Point d&#39;extension <code>register_submission_check</code> : déclaration au manifeste (validée à la construction), registre par organisation, lecture restreinte, exécution à l&#39;ouverture, à la correction et à la confirmation, 500 journalisé sans donnée saisie, 503 sur délai dépassé, exporté par <code>app.plugins</code>. — <code>apps/api/app/forms/submission_checks.py</code>, <code>apps/api/app/forms/submissions.py</code>, <code>apps/api/app/api/public_forms.py</code>, <code>apps/api/app/plugins/{manifest,composition,__init__}.py</code>. Preuves : <code>apps/api/tests/test_controle_de_soumission.py</code> — déclaration pour le type d&#39;une autre extension refusée, fonction synchrone refusée, une fonction par type, délai borné ; erreurs réunies par champ ; exception sans donnée dans le message ni le journal ; délai dépassé ; lecture restreinte (pas de brouillon, pas d&#39;autre organisation, pas de donnée personnelle, champ privé retranché).</li><li>[x] Enquête : refus d&#39;une réponse sans valeur non vide pour une question <code>obligatoire=True</code> de l&#39;enquête publiée référencée, erreur sur <code>reponses</code> (questions nommées) ou <code>enquete</code> (introuvable, non publiée, autre organisation) ; docstring (décision n°4) et aide <code>plugins.enquetes.aide.obligatoire</code> réécrites. — <code>apps/api/app/bundled_plugins/enquetes.py</code> (<code>controler_reponse_enquete</code>). Preuves : <code>apps/api/tests/test_enquetes.py::test_une_reponse_sans_la_question_obligatoire_est_refusee_sur_le_champ_reponses</code> (<strong>rouge avant</strong> : la réponse sans la question obligatoire était acceptée, 201 au lieu de 422 ; vert ensuite) ; <code>test_controle_de_soumission.py</code> (messages, enquête inconnue, brouillon, autre organisation, correction, enquête dépubliée avant « Envoyer »).</li><li>[ ] <strong>Appliquer <code>TextFieldDef.max_length</code> côté serveur.</strong> Déclaré et publié aux clients, non opposé par le validateur (titre du flash info : 55 caractères). À décider après un relevé des Content Types qui déclarent un <code>max_length</code> : leurs enregistrements existants ou leurs données de démonstration peuvent le dépasser.</li><li>[ ] <strong>Rendre les enquêtes dans le front public</strong> : un répéteur <code>reponses</code> saisi question par question, avec <code>required</code>/<code>aria-required</code> pour les questions obligatoires et l&#39;erreur du champ <code>reponses</code> rattachée à la question nommée. Le serveur refuse déjà la réponse incomplète.</li></ul>',21)])])}const m=t(r,[["render",i]]);export{g as __pageData,m as default};
